PRAGMA foreign_keys = ON;

CREATE TABLE users (id TEXT PRIMARY KEY, auth_subject TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deletion_pending INTEGER NOT NULL DEFAULT 0);
CREATE TABLE notes (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, markdown TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 0, provenance_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX notes_owner_updated ON notes(owner_id, updated_at DESC);
CREATE TABLE note_edits (id TEXT PRIMARY KEY, note_id TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, operation_id TEXT NOT NULL, base_revision INTEGER NOT NULL, result_revision INTEGER NOT NULL, before_title TEXT NOT NULL, before_markdown TEXT NOT NULL, before_provenance_json TEXT NOT NULL, after_title TEXT NOT NULL, after_markdown TEXT NOT NULL, after_provenance_json TEXT NOT NULL, undone INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(owner_id, note_id, operation_id));
CREATE INDEX note_edits_note_revision ON note_edits(note_id, result_revision DESC);
CREATE TABLE personas (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, prompt TEXT NOT NULL, brevity TEXT NOT NULL, challenge TEXT NOT NULL, tone TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX personas_owner ON personas(owner_id);
CREATE TABLE conversations (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, note_id TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE, persona_id TEXT, persona_snapshot_json TEXT, learning_consent INTEGER NOT NULL DEFAULT 0, last_user_activity_at TEXT NOT NULL, expires_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL);
CREATE INDEX conversations_expiry ON conversations(status, expires_at);
CREATE TABLE turns (id TEXT PRIMARY KEY, request_id TEXT NOT NULL, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, completed_at TEXT, UNIQUE(owner_id, request_id));
CREATE UNIQUE INDEX one_streaming_turn ON turns(conversation_id) WHERE status='streaming';
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, turn_id TEXT REFERENCES turns(id) ON DELETE SET NULL, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, annotations_json TEXT NOT NULL DEFAULT '[]', incomplete INTEGER NOT NULL DEFAULT 0, sequence INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(conversation_id, sequence));
CREATE INDEX messages_conversation ON messages(conversation_id, sequence);
CREATE TABLE interventions (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, turn_id TEXT NOT NULL REFERENCES turns(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_pending_intervention ON interventions(conversation_id) WHERE status='pending';
CREATE TABLE usage_periods (owner_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, plan TEXT NOT NULL DEFAULT 'free', used INTEGER NOT NULL DEFAULT 0, unit_limit INTEGER NOT NULL DEFAULT 10, resets_at TEXT NOT NULL, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0);
CREATE TABLE billing_customers (owner_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, customer_id TEXT NOT NULL UNIQUE, subscription_id TEXT, updated_at TEXT NOT NULL);
CREATE TABLE billing_events (id TEXT PRIMARY KEY, processed_at TEXT NOT NULL);
CREATE TABLE product_events (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, session_id TEXT NOT NULL, kind TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', occurred_at TEXT NOT NULL);
